function zonedParts(instant, timeZone) {
  const dtf = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
    fractionalSecondDigits: 3,
  });
  const map = {};
  for (const p of dtf.formatToParts(instant)) {
    if (p.type !== "literal") map[p.type] = p.value;
  }
  let hour = Number(map.hour);
  let day = Number(map.day);
  let month = Number(map.month);
  let year = Number(map.year);
  if (hour === 24) hour = 0;
  return {
    year, month, day, hour,
    minute: Number(map.minute),
    second: Number(map.second),
    millisecond: Number(map.fractionalSecond ?? "0"),
  };
}
function offsetMs(instant, timeZone) {
  const p = zonedParts(instant, timeZone);
  const asUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second, p.millisecond);
  return asUtc - instant.getTime();
}
function wallToUtc(y, m, d, h, mi, s, ms, timeZone) {
  const naive = Date.UTC(y, m - 1, d, h, mi, s, ms);
  let utc = naive;
  for (let i = 0; i < 4; i++) {
    const off = offsetMs(new Date(utc), timeZone);
    const next = naive - off;
    if (next === utc) break;
    utc = next;
  }
  return new Date(utc);
}
function show(label, date, tz) {
  const p = zonedParts(date, tz);
  console.log(label, date.toISOString(), "local", p);
}

// Tokyo start of 2026-03-16
const tokyoMidnight = wallToUtc(2026, 3, 16, 0, 0, 0, 0, "Asia/Tokyo");
show("tokyo midnight Mar 16", tokyoMidnight, "Asia/Tokyo");

// Kolkata
const kol = wallToUtc(2026, 3, 15, 0, 0, 0, 0, "Asia/Kolkata");
show("kolkata midnight Mar 15", kol, "Asia/Kolkata");

// Chatham
const ch = wallToUtc(2026, 3, 15, 0, 0, 0, 0, "Pacific/Chatham");
show("chatham midnight Mar 15", ch, "Pacific/Chatham");

// NY spring digest hour 4 on Mar 8 2026 10:00 EDT = 14:00Z
const nySpringNow = new Date("2026-03-08T14:00:00.000Z");
show("ny spring now", nySpringNow, "America/New_York");
const endSpring = wallToUtc(2026, 3, 8, 4, 0, 0, 0, "America/New_York");
const startSpring = wallToUtc(2026, 3, 7, 4, 0, 0, 0, "America/New_York");
show("ny spring end 4am", endSpring, "America/New_York");
show("ny spring start 4am", startSpring, "America/New_York");
console.log("spring hours", (endSpring - startSpring) / 3600000);

// NY fall Nov 1 2026 10:00 EST = 15:00Z
const nyFallNow = new Date("2026-11-01T15:00:00.000Z");
