function startOfDay(reference, timeZone) {
  const p = zonedParts(reference, timeZone);
  const target = p.year * 10000 + p.month * 100 + p.day;
  const ymd = (ms) => {
    const q = zonedParts(new Date(ms), timeZone);
    return q.year * 10000 + q.month * 100 + q.day;
  };
  const naive = Date.UTC(p.year, p.month - 1, p.day);
  let lo = naive - 36 * 3600_000;
  let hi = naive + 36 * 3600_000;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (ymd(mid) < target) lo = mid + 1;
    else hi = mid;
  }
  return new Date(lo);
}
