function zonedParts(instant, timeZone) {
  const dtf = new Intl.DateTimeFormat("en-US", {
    timeZone, year:"numeric", month:"2-digit", day:"2-digit",
    hour:"2-digit", minute:"2-digit", second:"2-digit", hourCycle:"h23", fractionalSecondDigits:3,
  });
  const map = {};
  for (const p of dtf.formatToParts(instant)) if (p.type !== "literal") map[p.type] = p.value;
  let hour = Number(map.hour);
  if (hour === 24) hour = 0;
  return { year:Number(map.year), month:Number(map.month), day:Number(map.day), hour, minute:Number(map.minute), second:Number(map.second), millisecond:Number(map.fractionalSecond??"0") };
}
function offsetMs(instant, timeZone) {
  const p = zonedParts(instant, timeZone);
  const asUtc = Date.UTC(p.year, p.month-1, p.day, p.hour, p.minute, p.second, p.millisecond);
  return asUtc - instant.getTime();
}
function wallToUtc(y,m,d,h,mi,s,ms,timeZone) {
  const naive = Date.UTC(y,m-1,d,h,mi,s,ms);
  let utc = naive;
  for (let i=0;i<4;i++) {
    const off = offsetMs(new Date(utc), timeZone);
    const next = naive - off;
    if (next === utc) break;
    utc = next;
  }
  return new Date(utc);
}
const gap2 = wallToUtc(2026,3,8,2,0,0,0,"America/New_York");
console.log("gap 2:00", gap2.toISOString(), zonedParts(gap2, "America/New_York"));

// later ambiguous: try starting from +1h naive
function allMatches(y,m,d,h,tz) {
  const naive = Date.UTC(y,m-1,d,h,0,0,0);
  const found = new Map();
  for (let delta=-20; delta<=20; delta++) {
    const guess = naive + delta*3600_000;
    const off = offsetMs(new Date(guess), tz);
    const instantMs = naive - off;
    const instant = new Date(instantMs);
    const p = zonedParts(instant, tz);
    if (p.year===y && p.month===m && p.day===d && p.hour===h && p.minute===0 && p.second===0 && p.millisecond===0) {
      found.set(instantMs, instant.toISOString());
    }
  }
  return [...found.entries()];
}
console.log("matches 1am Nov1", allMatches(2026,11,1,1,"America/New_York"));
