    return true;
  } catch {
    return false;
  }
}

/** Refuses a zone name `Intl` does not recognise. */
export function assertKnownTimeZone(timeZone: string): void {
  try {
    Intl.DateTimeFormat("en-US", { timeZone });
  } catch (error) {
    if (error instanceof RangeError) throw error;
    throw new RangeError(`Invalid time zone: ${timeZone}`);
  }
}

function pad(value: number): string {
  return String(value).padStart(2, "0");
}

function zonedParts(instant: Date, timeZone: string): ZonedParts {
  assertKnownTimeZone(timeZone);
  const formatted = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
    fractionalSecondDigits: 3,
  }).formatToParts(instant);

  const map: Record<string, string> = {};
  for (const part of formatted) {
    if (part.type !== "literal") map[part.type] = part.value;
  }

  let hour = Number(map.hour);
  // Some engines report midnight as hour 24 on the same calendar date.
  if (hour === 24) hour = 0;

  return {
    year: Number(map.year),
    month: Number(map.month),
    day: Number(map.day),
    hour,
    minute: Number(map.minute),
    second: Number(map.second),
    millisecond: Number(map.fractionalSecond ?? "0"),
  };
}

function timeZoneOffsetMs(instant: Date, timeZone: string): number {
  const parts = zonedParts(instant, timeZone);
  const asUtc = Date.UTC(
    parts.year,
    parts.month - 1,
    parts.day,
    parts.hour,
    parts.minute,
    parts.second,
    parts.millisecond,
  );
  return asUtc - instant.getTime();
}

function shiftCalendarDate(
  year: number,
  month: number,
  day: number,
  days: number,
): { year: number; month: number; day: number } {
  const shifted = new Date(Date.UTC(year, month - 1, day + days));
  return {
    year: shifted.getUTCFullYear(),
    month: shifted.getUTCMonth() + 1,
    day: shifted.getUTCDate(),
  };
}

/** Every real instant at which `timeZone` shows `hour:00:00.000` on that date. */
function instantsAtLocalHour(
  year: number,
  month: number,
  day: number,
  hour: number,
  timeZone: string,
): Date[] {
  const naive = Date.UTC(year, month - 1, day, hour, 0, 0, 0);
  const found = new Map<number, Date>();

  for (let delta = -20; delta <= 20; delta += 1) {
    const guess = naive + delta * HOUR_MS;
    const offset = timeZoneOffsetMs(new Date(guess), timeZone);
    const instantMs = naive - offset;
    const instant = new Date(instantMs);
    const parts = zonedParts(instant, timeZone);
    if (
      parts.year === year &&
      parts.month === month &&
      parts.day === day &&
      parts.hour === hour &&
      parts.minute === 0 &&
      parts.second === 0 &&
      parts.millisecond === 0
    ) {
      found.set(instantMs, instant);
    }
  }

  return [...found.values()].sort((a, b) => a.getTime() - b.getTime());
}

/** First instant whose local calendar date is `year-month-day`. */
function startOfCalendarDate(
  year: number,
  month: number,
  day: number,
  timeZone: string,
): Date {
  assertKnownTimeZone(timeZone);
  const target = year * 10_000 + month * 100 + day;
  const naive = Date.UTC(year, month - 1, day);
  let lo = naive - 36 * HOUR_MS;
  let hi = naive + 36 * HOUR_MS;

  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    const parts = zonedParts(new Date(mid), timeZone);
    const value = parts.year * 10_000 + parts.month * 100 + parts.day;
    if (value < target) lo = mid + 1;
    else hi = mid;
  }

  return new Date(lo);
}

/** `YYYY-MM-DD` of `value` on the clock in `timeZone`. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const parts = zonedParts(parseIso(value), timeZone);
  return `${parts.year}-${pad(parts.month)}-${pad(parts.day)}`;
}

/** Hour 0–23 of `instant` on the clock in `timeZone`. */
export function localHour(instant: Date, timeZone: string): number {
  return zonedParts(instant, timeZone).hour;
}

/**
 * UTC instant at which the calendar day containing `reference` began in
 * `timeZone`, written the way `toIsoTimestamp` writes every other stamp.
 */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const parts = zonedParts(reference, timeZone);
  return toIsoTimestamp(
    startOfCalendarDate(parts.year, parts.month, parts.day, timeZone),
  );
}

/**
 * Local midnight of the calendar date `days` away from the local date that
 * contains `reference`. Negative `days` step backward. The span is calendar
 * days, so a DST change does not add or drop a day.
 */
export function shiftLocalMidnight(
  reference: Date,
  days: number,
  timeZone: string,
): IsoTimestamp {
  const parts = zonedParts(reference, timeZone);
  const shifted = shiftCalendarDate(parts.year, parts.month, parts.day, days);
  return toIsoTimestamp(
    startOfCalendarDate(shifted.year, shifted.month, shifted.day, timeZone),
  );
}

function plural(count: number, unit: string): string {
  return `${count} ${unit}${count === 1 ? "" : "s"}`;
}

/**
 * "just now" / "5 minutes ago" / "in 2 days" — the wording the activity feed,
 * issue cards and comment headers all use.
 */
export function formatRelative(
  value: IsoTimestamp,
  reference: Date = new Date(),
): string {
  const deltaMs = parseIso(value).getTime() - reference.getTime();
  const past = deltaMs < 0;
  const abs = Math.abs(deltaMs);

  const phrase = ((): string => {
    if (abs < MINUTE_MS) return "just now";
    if (abs < HOUR_MS) return plural(Math.floor(abs / MINUTE_MS), "minute");
    if (abs < DAY_MS) return plural(Math.floor(abs / HOUR_MS), "hour");
    if (abs < WEEK_MS) return plural(Math.floor(abs / DAY_MS), "day");
    if (abs < 30 * DAY_MS) return plural(Math.floor(abs / WEEK_MS), "week");
    if (abs < 365 * DAY_MS) return plural(Math.floor(abs / (30 * DAY_MS)), "month");
    return plural(Math.floor(abs / (365 * DAY_MS)), "year");
  })();

  if (phrase === "just now") return phrase;
  return past ? `${phrase} ago` : `in ${phrase}`;
}

/** Absolute calendar rendering, e.g. "12 Mar 2026", in the given timezone. */
export function formatDate(value: IsoTimestamp, timezone = "UTC"): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: timezone,
  }).format(parseIso(value));
}

/**
 * True once the workspace calendar day that contains `dueAt` has ended.
 * On that day itself the issue is not overdue, whatever time `dueAt` names.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  const dueDay = localDate(dueAt, timeZone);
  const today = localDate(toIsoTimestamp(reference), timeZone);
  return dueDay < today;
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The window a digest covers. It ends at the most recent local `hour:00` at
 * or before `reference` (today's if that hour has passed, otherwise
 * yesterday's) and starts at the same local hour on the previous calendar
 * day. Across a DST change the span is 23 or 25 hours.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHour}`);
  }
  assertKnownTimeZone(timeZone);

  const today = zonedParts(reference, timeZone);
  const candidates = [0, -1, -2].flatMap((delta) => {
    const day = shiftCalendarDate(today.year, today.month, today.day, delta);
    return instantsAtLocalHour(day.year, day.month, day.day, digestHour, timeZone);
  });

  const end = candidates
    .filter((instant) => instant.getTime() <= reference.getTime())
    .sort((left, right) => right.getTime() - left.getTime())[0];

  if (!end) {
    throw new RangeError(
      `No digest boundary at hour ${digestHour} in ${timeZone}`,
    );
  }

  const endParts = zonedParts(end, timeZone);
  const endMatches = instantsAtLocalHour(
    endParts.year,
    endParts.month,
    endParts.day,
    digestHour,
    timeZone,
  );
  const index = Math.max(
    0,
    endMatches.findIndex((instant) => instant.getTime() === end.getTime()),
  );
  const previous = shiftCalendarDate(endParts.year, endParts.month, endParts.day, -1);
  const startMatches = instantsAtLocalHour(
    previous.year,
    previous.month,
    previous.day,
    digestHour,
    timeZone,
  );
  const start = startMatches[Math.min(index, startMatches.length - 1)];

  if (!start) {
    throw new RangeError(`No digest start at hour ${digestHour} in ${timeZone}`);
  }

  return {
    start: toIsoTimestamp(start),
    end: toIsoTimestamp(end),
  };
}
