function workspaceTimeZone(orgId: OrgId): string {
  const row = getDb()
    .select({ timeZone: organizations.timeZone })
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row?.timeZone ?? "UTC";
}

/**
 * Live, still-open issues whose due calendar day has ended on the workspace
 * clock. `now` is the instant the decision is made; the day that contains a
 * due date is not overdue yet.
 */
export async function listOverdueIssues(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<readonly Issue[]> {
  const cutoff = startOfLocalDay(parseIso(now), workspaceTimeZone(orgId));
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          isNotNull(issues.dueAt),
          lt(issues.dueAt, cutoff),
          inArray(issues.status, ["backlog", "todo", "in_progress", "in_review"]),
        ),
      ),
    )

