it("treats a due date as a whole local day", () => {
  expect(isOverdue(null, REFERENCE)).toBe(false);
  // Same UTC day as the reference: not overdue yet, whatever the clock time.
  expect(isOverdue(iso("2026-03-15T00:00:00.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T12:00:01.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T23:59:59.000Z"), REFERENCE)).toBe(false);
  // The previous calendar day has ended; a later day has not.
  expect(isOverdue(iso("2026-03-14T23:59:59.000Z"), REFERENCE)).toBe(true);
  expect(isOverdue(iso("2026-03-16T00:00:00.000Z"), REFERENCE)).toBe(false);

  // 2026-03-15T16:00Z is 2026-03-16 01:00 in Tokyo. A due instant still on
  // that local day is not overdue; the previous local day is.
  const tokyoEvening = new Date("2026-03-15T16:00:00.000Z");
  expect(isOverdue(iso("2026-03-15T15:30:00.000Z"), tokyoEvening, "Asia/Tokyo")).toBe(
    false,
  );
  expect(isOverdue(iso("2026-03-14T14:00:00.000Z"), tokyoEvening, "Asia/Tokyo")).toBe(
    true,
  );
});

it("names the local calendar date and the instant that day began", () => {
  expect(localDate(iso("2026-03-15T16:00:00.000Z"), "UTC")).toBe("2026-03-15");
  expect(localDate(iso("2026-03-15T16:00:00.000Z"), "Asia/Tokyo")).toBe("2026-03-16");
